  'consent.body':
    'Єдині кукі, які ми радимо, — не для їжі: вони допомагають нам покращувати сайт. Дякуємо.',
  'consent.acceptAll': 'Дозволити все',
  'consent.necessary': 'Лише необхідне',
  'consent.settings': 'Обрати',
  'consent.save': 'Зберегти',
  'consent.analytics.label': 'Аналітика та записи',
  'consent.analytics.desc':
    'Повна аналітика та записи сесій — щоб ми бачили, де друзі собак застрягають.',
  'consent.marketing.label': 'Маркетинг',
  "consent.marketing.desc": "Рекламні cookies (як-от Meta Pixel), щоб охоплювати нових друзів собак. Поки ми жодних не використовуємо; ваш вибір набуде чинності, коли почнемо.",
  'consent.footerLink': 'Налаштування cookies',

