  "transparency.part.community": "Розвиток спільноти",
  "transparency.part.community.note": "Двигун руху: 5 € іде на розвиток DOGYPT, 3 € — людям, які несуть віру.",
  "transparency.part.development.note": "Будуємо націю й фінансуємо все, на чому вона тримається, — людей, які рухають DOGYPT уперед, і сервіси, інструменти й сервери за ними. Це двигун руху, і кожна окрема витрата буде задокументована та відкрито оприлюднена.",
  "transparency.part.affiliate.note": "Не реклама, а люди. Це йде напряму догиптіанам, які несуть віру, у BONES, внутрішній валюті зграї. Ми вкладаємо у зграю, а не в дорогий маркетинг: зграя несе слово значно далі.",
  "transparency.part.directHelp.note": "Прямо до псів у біді — притулки, корм, ветеринарні рахунки та рятувальні місії. Жодних посередників, жодних накладних витрат: ця частка йде туди, де є страждання, і кожен цент задокументований, підтверджений квитанцією та відкритий для всієї зграї.",
  "transparency.part.hekthorBowl.note": "Пес-засновник, який усе це почав. Ця частка — прозора винагорода для Hekthor і його господаря, просто їхня зарплата. Їхня мета — стати мільйонерами: мільйон псів у зграї. Без Hekthor DOGYPT ніколи б не з'явився — ця миска і є подяка.",
