  "entry.criteria.offerings.tag": "100% прозорість",
  "entry.criteria.offerings.body": "€11, один раз. Символічна пожертва — кожен дохід і кожна витрата в книзі, відкритій для всіх. Енергія, що тримає нас живими.",
