  "pack.will.eyebrow": "Заповіт",
  "pack.will.title": "Якби тебе тут не було",
  "pack.will.intro": "Усе на цій картці — вже передання. Це частина, яку отримає лише він: хто перебирає пса і що йому варто знати.",
