  "pack.wizard.welcome.title": "Привіт, людино!",
  "pack.wizard.k0.title": "Вітаємо в DOGYPT!",
  "pack.wizard.k0.vitaj": "Я проведу тобі швидку екскурсію нашим храмом, щоб ти тут не блукав розгублений. Згоден?",
  "pack.wizard.k0.dar": "Отримаєш значок!",
  "pack.wizard.k0.ano": "Так",
  "pack.wizard.k0.neskor": "Пізніше",
  "pack.wizard.k0.feed": "<b>FEED.</b> Головний екран і класична стрічка дописів, як в Instagram (звісно, з кращим контентом!) Можеш стежити за новинами, додавати фото, реагувати, надихатися…",
  "pack.wizard.k0.mapa": "<b>МАПА.</b> Разом ми творимо собачий світ, де знайдемо все важливе. Ми постійно над нею працюємо, покращуємо її і додаємо нове. Дякуємо за допомогу й терпіння!",
  "pack.wizard.k0.labka": "<b>ЛАПКА.</b> Кнопка дії, якою ти додаєш речі залежно від екрана, на якому ти зараз!",
  "pack.wizard.k0.ainubis": "<b>МОЗОК AINUBIS.</b> Освітня частина з собачими знаннями, корисним скролінгом і подкастами. Контенту постійно більшає, зокрема й завдяки вам.",
  "pack.wizard.k0.menu": "Угорі <b>ТВІЙ ПРОФІЛЬ</b>, унизу <b>ТВОЯ ЗГРАЯ</b>. Подвійний дотик до фото відкриває другий варіант, як в Instagram.",
  "pack.wizard.k1.fotka": "<b>МОЯ ЗГРАЯ.</b> Тут уся документація твоїх собак. Мати всю інформацію про пса в одному місці це відповідальний і корисний вчинок. Торкнися тут і вибери його найкраще фото.",
  "pack.wizard.k1.zivot": "<b>ЖИТТЯ.</b> Гола реальність у місяцях: скільки зазвичай живе його порода і скільки за кращого догляду. Щоб ти не відкладав пригоди «на потім».",
  "pack.wizard.k1.dennik": "<b>ЩОДЕННИК.</b> Тут зберігаються всі ваші щоденні записи. Ти додаєш їх через регулярний запис дня.",
  "pack.wizard.k1.vyplnit": "<b>DOG ID</b> це детальний квіз про твого пса. Усю інформацію про нього оцінить, наприклад, ветеринар, а також я, коли тобі знадобиться порада саме для вас. Торкнися Заповнити, і почнімо.",
  "pack.wizard.k2.levely": "Твої рівні в DOGYPT: <b>Слуга</b> = роки з псом, <b>Прочанин</b> = мандрівки/кілометри, <b>Учень</b> = знання/сувої.",
  "pack.wizard.k2.zapis": "<b>Запис дня</b> це швидкий підсумок того, що ви разом пережили. Можеш записати й минулі дні та спланувати наперед.",
  "pack.wizard.k3.pas": "Тут найновіші <b>сповіщення</b>, <b>повідомлення</b> і меню <b>SOS</b>.",
  "pack.wizard.k4.vrstvy": "<b>Шари:</b> фільтр, яким налаштуєш, що бачиш на мапі: гадюки, місця для ночівлі, ветеринари, TRIPWISH…",
  "pack.wizard.k4.vylety": "Мандрівки та події. Пройдеш маршрут, позначиш його, і кілометри додадуться.",
  "pack.wizard.k4.labka": "Власну мандрівку створиш через лапку. Це справді легко, наклацаєш її за 3 хвилинки.",
  "pack.wizard.k5.cta": "<b>SNIFFER</b> шукає друзів для мандрівок. Коли ви обоє дасте одне одному SNIFF, зможете листуватися й домовитися про прогулянку.",
  "pack.wizard.k6.planes": "<b>Сувої</b> це коротке читання на різні теми. <b>Чат</b> знає весь цей мозок. <b>Джерела</b> це бібліотека, до якої можеш долучитися й ти, наприклад книжкою чи статтею.",
  "pack.wizard.k6.zvitky": "Кожен прочитаний сувій зараховується до твого прогресу. Скільки ти вивчаєш пса, настільки ти його справді любиш.",
  "pack.wizard.k.odz.uvod": "Перший день у храмі",
  "pack.wizard.k.odz.pes": "Охоронець пса",
