  "pack.wizard.k.novinky.title": "Що нового",
  "pack.wizard.k.novinky.body": "Храм має кімнати. Коли біля мене засвітиться ключик, у мене є для тебе нова. За кожну кімнату ти відімкнеш двері й отримаєш значок. Перший твій за цю новину.",
  "pack.wizard.k.novinky.ok": "Зрозуміло",
