  "pack.wizard.k.pripomienka": "Привіт, {name}, маєш хвилинку? Заповнімо DOG ID, це кілька хвилин.",
  "pack.wizard.k.clovek": "друже",
  "pack.wizard.k.podme": "Уперед",
  "pack.wizard.k.kluc": "Покажи покій",
  "pack.wizard.k.znovu": "Пройти екскурсію знову",
  "pack.wizard.k.reset": "Скинути екскурсію (тест)",
  "pack.wizard.k0.fotkaTuk": "Торкнися свого фото.",
  "pack.wizard.k0.aiTuk": "І наостанок я. Торкнися моєї іконки.",
  "pack.wizard.k0.preslov": "Мою іконку знайдеш майже на кожному екрані, я завжди тут для тебе. Коли щось не працює, торкнися <b>мішені</b>: я зроблю скриншот, а ти лише позначиш місце, без фото в телефоні. А коли біля мене засвітиться <b>ключик</b>, у мене для тебе новинка, яку я поясню.",
  "pack.wizard.k1.navFotka": "Торкнися свого фото.",
  "pack.wizard.k1.navSvorka": "Торкнися <b>ЗГРАЇ</b>.",
  "pack.wizard.k1.zivotTuk": "Торкнися <b>Життя</b>.",
  "pack.wizard.k1.dennikTuk": "Торкнися <b>Щоденника</b>.",
  "pack.wizard.k1.dogTuk": "Торкнися <b>DOG ID</b>.",
  "pack.wizard.k2.navFotka": "Торкнися свого фото.",
  "pack.wizard.k2.navProfil": "Торкнися <b>ПРОФІЛЮ</b>.",
  "pack.wizard.k2.bones": "<b>BONES</b> — внутрішня валюта DOGYPT. Ти отримуєш їх за кожного друга, якого приводиш. Пізніше їх можна буде обміняти, наприклад, на мерч.",
  "pack.wizard.k2.pozvi": "<b>Запросити</b> надсилає твоє посилання друзям. DOGYPT росте саме так, будь частиною нашого зростання.",
  "pack.wizard.k2.upravit": "<b>Редагувати профіль:</b> тут налаштуєш свої дані, те, як тебе бачать інші, і налаштування застосунку.",
  "pack.wizard.k2.labkaTuk": "Торкнися <b>лапки</b>.",
  "pack.wizard.k3.kolesoTuk": "Торкнися <b>рятувального круга</b>.",
  "pack.wizard.k3.koleso": "<b>SOS.</b> Корисні функції, які можуть врятувати життя, якщо твій пес у небезпеці. Віримо, що вони тобі ніколи не знадобляться, але краще бути готовим!",
  "pack.wizard.k4.navTuk": "Торкнися <b>МАПИ</b>.",
