  "magnet.lock.h": "Далі — лише догіптяни",
  "magnet.lock.p": "Ключ — герогліф твого пса: €11 раз і назавжди. Кожен похід, кожен звиток із подкастом і AINUBIS.",
  "magnet.pv.tryAdd": "Спробуй додати похід",
  "magnet.lock.eye.save": "Запис походу",
  "magnet.lock.save.h": "Збережи його як догіптянин",
  "magnet.lock.save.p": "Це була пробна спроба — похід не збережено. Догіптяни тримають свої походи в Triplist, збирають кілометри й бали, а зграя бачить, де вони були.",
  "magnet.lock.login": "Я догіптянин — увійти",
  "magnet.backShort": "Назад",
  "magnet.lock.ai.eye": "Ексклюзивний контент",
  "magnet.lock.ai.h": "Only Paws",
  "magnet.lock.ai.p": "Так, у нас теж є ексклюзивний контент. Наш — про собак, тож його не треба ні від кого ховати. €11 раз і назавжди — менше, ніж один похід у кав'ярню. Цього разу візьми із собою пса. Каву він не питиме, але цей застосунок полюбить.",
  "magnet.lock.ai.stay": "Ще понюхаю безкоштовно",
  "magnet.info.eye": "Що тут живе",
  "magnet.info.ok": "Зрозуміло",
  "magnet.info.ask": "Що це?",
  "magnet.info.events.h": "Події",
  "magnet.info.events.p": "Собачі події в одному місці — виставки, забіги, зустрічі, спільні походи. Додати подію може будь-хто зі зграї. Дай знати, чи йдеш або цікавишся, і подивись, хто ще прийде.",
  "magnet.info.sniffer.h": "SNIFFER",
  "magnet.info.sniffer.p": "Знаходить тобі компанію для походів. Показує любителів собак, які тобі пасують — торкнись SNIFF, Ні або одразу напиши їм. Щоб ти не ходив горами лише з власними думками.",
  "magnet.info.notif.h": "Сповіщення",
  "magnet.info.notif.p": "Тут застосунок каже тобі, що відбувається в зграї: хто щойно приєднався, хто хоче до твого походу, хто пройшов твій маршрут і хто хоче туди, куди й ти.",
  "magnet.info.msgs.h": "Повідомлення",
  "magnet.info.msgs.p": "Приватні повідомлення між догіптянами. Домовтеся про спільний похід, надішли пораду щодо маршруту або нарешті спитай, як звати того пса з фото.",
  "magnet.info.wish.h": "TRIPWISH",
  "magnet.info.wish.p": "Бажання, а не план. Прикріпи місце, яке тебе кличе — вершину, місто чи цілу країну — і приблизно коли. Зграя це бачить, і хто теж хоче туди, озветься.",
  "magnet.info.want.h": "Хочу піти",
  "magnet.info.want.p": "Походи, які ти зберіг із карти. Коли пройдеш їх, вони перейдуть до пройдених, а тобі нарахуються кілометри й бали.",
  "magnet.info.chat.h": "Чат з AINUBIS",
  "magnet.info.chat.p": "Ти питаєш, AINUBIS відповідає — про здоров'я, годування, виховання, походи й про те, чому твій пес їсть траву. Догіптяни мають його під рукою вдень і вночі.",
  "magnet.info.forum.h": "Форум",
  "magnet.info.forum.p": "Дошка зграї — питання, досвід і поради від любителів собак для любителів собак. Ми саме його доробляємо, і догіптяни будуть там першими.",
  "magnet.info.sources.h": "Джерела",
  "magnet.info.sources.p": "На чому стоїть мозок AINUBIS: понад 12 000 сторінок A4 — 5,5 мільйона слів із 332 інтерв'ю, книжок, 151 наукового дослідження, 894 відео та 264 статей. Жодного «сусід казав» — біля кожного звитка видно, звідки це знання. І кожен догіптянин може додати власне джерело.",
  "magnet.ai.trips.h": "10 походів на пробу",
  "magnet.ai.trips.p": "Решту {n} ти бачиш, але не зайдеш — як пес перед м'ясною крамницею. Догіптяни записують власні походи, збирають кілометри й бали. Я рахую і ніколи не помиляюся. Майже.",
  "magnet.ai.trips.bar": "Решту походів ти бачиш, але не зайдеш — як пес перед м'ясною крамницею.",
  "magnet.ai.vault.h": "Перше коло — повністю твоє",
  "magnet.ai.vault.p": "10 звитків із подкастом про те, звідки взявся пес. Решту {n} охороняє пес. Цей пес — я, і хабар беру лише один: €11, раз і назавжди.",
  "magnet.ai.vault.bar": "Решту звитків охороняє пес. Цей пес — я.",
  "magnet.ai.stats.h": "Чужі цифри, власна заздрість",
  "magnet.ai.stats.bar": "Це кілометри Matej. Твоїх тут поки немає — Hekthor прокоментував це одним поглядом.",
  "magnet.ai.article.h": "Цей похід — за наш рахунок",
  "magnet.ai.article.bar": "Маршрут, парковка й навігація — твої. Коментувати можуть лише догіптяни — щоб тут ніхто не гавкав на чужих.",
