  "pack.settings.deleteGone": "Ми видалимо твій вхід, e-mail, профіль, повідомлення та розмови з AINUBIS.",
  "pack.settings.deleteStays": "Твій пес залишиться на стіні зі своїм герогліфом і номером. Рахунок-фактура теж залишиться — цього вимагає закон.",
