  "login.deleted": "Твій акаунт буде видалено {date}. Передумав? Увійди й скасуй видалення.",
  "pack.wizard.ainubis.intro": "Я AINUBIS — головний автономний AI-агент DOGYPT. Я стежу за безпекою і за тим, щоб усе працювало, а ще я — джерело всієї інформації.",
  "pack.wizard.profile.bones": "Твої BONES і посилання, яким ти запросиш друзів. Саме так росте DOGYPT — будь ласка, стань частиною цього.",
  "pack.wizard.profile.pilgrim": "Твій ПАЛОМНИК: рівень, кілометри й походи.",
  "pack.wizard.profile.head": "Ім'я, прізвисько й назва зграї. Обери, як тебе бачитиме зграя.",
  "pack.wizard.sniffer.card": "SNIFFER шукає компанію для походів. Спершу заповни профіль на 100 %, потім SNIFF або Ні. Коли ви обоє дасте SNIFF, зможете писати одне одному.",
  "pack.wizard.ainubis.scroll": "DOGSCROLL: звитки один за одним. Прочитай один, «запиши його в мозок» — і засвітиться зернятко.",
  "pack.wizard.ainubis.planes": "Dog Sense — це знання про собак, CHAT — розмова зі мною, FORUM — дошка оголошень зграї.",
  "pack.wizard.ainubis.me": "МОЇ ЗНАННЯ: я пропоную цікаві, корисні й перевірені знання зі світу собак. Скільки ти вивчаєш свого пса, стільки й любиш його. Кожен прочитаний звиток записується у твій прогрес і статистику.",
  "pack.wizard.dogs.calendar": "Календар і все життя твого пса в блоках. Записи зі щоденника потрапляють сюди самі.",
  "pack.wizard.dogs.quiz": "Квіз характеру (3 хвилини) розкриє стихію твого пса та його роль у зграї.",
  "pack.wizard.dogs.tiles": "Кожна плитка — це частина DOG ID. Що більше заповниш, то краще я зможу порадити.",
  "pack.wizard.dogs.block": "Твій пес коротко: номер, ім'я та герогліф. Відсоток праворуч показує, наскільки заповнений DOG ID.",
  "pack.wizard.tripArticle.problem": "Щось не так? Повідом — ми розберемося!",
  "pack.wizard.tripArticle.review": "Оцінки в лапках і поради від зграї. Оцінити можна, коли позначиш похід як пройдений.",
  "pack.wizard.tripArticle.go": "Навігація до старту й маршрут у телефон у Mapy.com.",
  "pack.wizard.tripArticle.walked": "Коли пройдеш його, познач. Нарахуються кілометри й бали — скільки, видно на пігулці.",
  "pack.wizard.triplist.wish": "TRIPWISH — це місце, куди ти колись хочеш потрапити. Познач його просто на карті, щоб не забути! «Шукаю компанію» бачить уся зграя, «Лише для мене» — тільки ти. Додай через + ДОДАТИ.",
  "pack.wizard.triplist.want": "Хочу піти: походи, які ти зберіг. Тут ти до них повернешся.",
  "pack.wizard.triplist.tabs": "Дві вкладки: TRIPLIST — твої походи, TRIPSTATS — твоя статистика: кілометри, походи й гірські хребти…",
  "pack.wizard.map.plus": "На карті «+» пропонує, що тут можна зробити: похід, TRIPWISH, швидку нотатку чи подію.",
  "pack.wizard.map.list": "Карта чи список походів — перемикай тут.",
  "pack.wizard.map.note": "Числа в кружечках — походи поблизу: наблизь, і вони розпадуться на мітки. Щоб залишити зграї нотатку (попередження, парковка, порада), скористайся «+» посередині панелі.",
  "pack.wizard.map.layers": "Шари карти: підкладка і те, що зверху — попередження зграї, гадюки, місця для ночівлі, TRIPWISH…",
  "pack.wizard.map.cats": "Перемикайся між тим, що пропонує карта. SNIFFER — це «собачий Tinder», він допоможе знайти компанію для походів.",
  "pack.wizard.map.search": "Шукай місце просто на карті або звузь вибір фільтрами: регіон, активності, теги.",
  "pack.wizard.map.pilgrim": "Привіт, ПАЛОМНИКУ! Тут ти бачиш свій рівень, кілометри й пройдені походи. Кожен пройдений км — це бал, а ще бали даються за додавання походу. Торкнись тут, щоб побачити свої походи й статистику.",
  "pack.wizard.navAinubis.body": "А це я. Тут живе Dog Sense — знання про собак, звиток за звитком — і наш чат. Коли потрібна порада, торкнись мене. Я нікуди не йду.",
  "pack.wizard.navMe.body": "Ти. Твій профіль і вся твоя зграя — кожен пес із власним DOG ID.",
  "pack.wizard.navAdd.body": "Через «+» ти додаєш те, що ви щойно пережили: похід, TRIPWISH, sniff чи сторінку щоденника. Пропозиції змінюються залежно від того, де ти зараз.",
