  'pack.vizia.heroglyf.text': "Перший собачий символ з'явився під час запуску DOGYPT.",
  'pack.vizia.intro':"Плани, про які ми мріємо. Торкнися лапки біля тих, що тобі потрібні, і залиш коментар.",
  'pack.vizia.kind.done': "Готово",
  'pack.vizia.kind.wip': "Зараз працюємо",
  'pack.vizia.kruhy.dogma':"6.4: де б не зустрілися двоє догіптян із собаками, там є DOGYPT.",
  'pack.vizia.kruhy.name': "Місцеві кола",
  'pack.vizia.kruhy.text': "Зустрічі догіптян у місті: парк для собак, прогулянка, кава.",
  'pack.vizia.land.dogma': "6.3: ціль на покоління, не термінова.",
  'pack.vizia.land.name': "DOGYPTLAND",
  'pack.vizia.land.text': "Діснейленд для собак: чудовий парк, майданчики для бігу, тренувальні поля, басейн, озеро та поросла травою піраміда з кав'ярнею, а ще ветеринар та інші крамниці. Просто рай для собачників.",
  'pack.vizia.liecitelia.name': "Платформа для цілителів тварин",
  'pack.vizia.liecitelia.text': "Фізіотерапевти, зоопсихологи, консультанти з харчування... Фахівці, які розв'язують проблеми альтернативним шляхом.",
  'pack.vizia.mapa.name': "Мапа прогулянок із псом",
  'pack.vizia.mapa.text': "Прогулянки, паркінги та місця на природі. Запиши прогулянку, і вона залишиться у твоєму щоденнику.",
  'pack.vizia.pomoc.dogma': "1 000 000 собак: друга династія.",
  'pack.vizia.pomoc.name': "Перша допомога у великому масштабі",
  'pack.vizia.pomoc.text': "Наша найвища мета, щоб кожен пес мав свою родину. Ми знаємо, що це звучить неймовірно, АЛЕ якщо постараємося, то зможемо принаймні наблизитися до цього і врятувати мільйони життів! Пес завжди виконає свою роль ідеального друга, решта залежить від нас.",
  'pack.vizia.stage.1': "Мріємо",
  'pack.vizia.stage.2': "Готуємо",
  'pack.vizia.stage.3': "Будуємо",
  'pack.vizia.stena.name': "Стіна псів",
  'pack.vizia.stena.text': "Кожен пес зі своїм герогліфом на головній сторінці.",
  'pack.vizia.title':"Що ми будуємо",
  'pack.vizia.utulky.dogma': "1 000 собак: перше партнерство з притулком.",
  'pack.vizia.utulky.name': "Притулки",
  'pack.vizia.utulky.text': "Уяви притулок, у якому тобі хотілося б працювати! Гарне, сучасне, чисте місце і лише дуже добрі люди, які працюють з любов'ю і отримують зарплату від нас, від DOGYPT. Притулки більше не були б сумними місцями, а стали б тренувальними центрами, де кожен пес має свою роботу, а за потреби собаки могли б допомагати, наприклад, у пошуках, у лікарнях чи під час інших катастроф...",
  'pack.vizia.zbierky.dogma': "Допомога собакам у біді це візія з умовою.",
  'pack.vizia.zbierky.name': "Збори для собак",
  'pack.vizia.zbierky.text': "Дорога операція? Надішли історію тисячам людей у DOGYPT. Якщо кожен дасть лише 1 євро, лікування раптом стане доступним, а жах перетвориться на гарну історію нашої єдності з псом, який житиме завдяки нам.",
  'ainubis.chat.v2.disclaimer': "AINUBIS у бета-версії. Він відповідає лише за нашими сувоями (собачий розум) і може помилятися. У разі загрози здоров'ю телефонуй ветеринару.",
