  "pack.misia.giftTitle": "Дар",
  "pack.misia.sofar": "Досі",
  "pack.misia.perMonth": "Щомісяця",
  "pack.misia.live": "Цифри надходять наживо зі скарбниці, вручну нічого не вписується.",
  "pack.misia.gift.p": "Добровільний дар, щомісяця або разово. Він нічого не відмикає — тому це дар, а не членство. Після комісії Stripe усе йде на розвиток DOGYPT.",
  "pack.misia.merch.p": "Футболки, нашивки й речі для собак. Те, що вони заробляють, іде до скарбниці.",
  "pack.misia.more.p": "Ми додамо лише ті джерела, яким не потрібні реклама й інвестори.",
  "pack.misia.run.p": "Щоб DOGYPT узагалі працював: сервери, AI, пошта, ліцензії застосунку. Це оплачуємо насамперед.",
  "pack.misia.app.p": "Розробка застосунку: програми, техніка, люди й сервіси. Сьогодні Матей будує його сам і без зарплати.",
  "pack.misia.res.p": "Як жити з псом довше й здоровіше: протокол довголіття, AI-ветеринар, добавки, що мають сенс.",
  "pack.misia.gear.p": "Власне спорядження для собак та їхніх людей, наприклад GPS-нашийник.",
  "pack.misia.help.p": "Що DOGYPT дає собакам у біді. Кожні {n} ідуть наступному притулку, зараз це {shelter}.",
  "pack.misia.v1": "*Наше бачення: DOGYPT, яким може користуватися кожен собачник.* Усе про собак і все життя твого пса в одному місці.",
  "pack.misia.v2": "Ми не хочемо йти бізнесовим шляхом. Реклама, кампанії й інвестори рано чи пізно вбивають дух ідеї.",
  "pack.misia.v3": "*Але ніщо не буває безкоштовним.* Сервери, розробка застосунку, люди й сервіси щомісяця коштують грошей. Що більше з цього понесуть *добровільні дари* зграї, то відкритішим може залишатися DOGYPT.",
  "pack.misia.v4": "Небагато достатньо. Коли нас буде більше, ми оплатимо роботу й розробку, а решта піде собакам: тим, хто в біді, дослідженням здоров'я й новому спорядженню.",
  "pack.misia.v5": "Скарбниця відкрита. Ти бачиш, що надійшло і куди пішло, а куди піде далі, вирішимо разом.",
  "pack.misia.v6": "*Безпечне місце для нас і наших собак.*",
