  "pack.flow.z_kastr.o.yes": "Ні, стерилізований (вазектомія)",
  "pack.flow.z_kastr.o.yes.warn": "<b>За останніми даними, краще обрати вазектомію.</b> Вона механічно запобігає заплідненню, а гормони залишаються; самиці можна зберегти яєчники. Класичну кастрацію роби лише після дорослішання: це залежить від розвитку й породи, пса чи суку не раніше, ніж після статевого дозрівання, великі породи якомога пізніше. У французьких бульдогів кастрація до 12 місяців підвищувала ризик проблем із міжхребцевими дисками приблизно у 2× у самців і приблизно в 10× у самиць.",
