  "pack.flow.z_kastr.o.no.sub.kennel.warn": "Розводити собак допустимо лише тоді, коли тварина живе в гідних умовах, під професійним наглядом, із відомим родоводом та історією.",
  "pack.flow.z_kastr.o.no.sub.kennel.warnT": "Що треба знати про розведення",
  "pack.flow.z_kastr.o.no.sub.plan_neuter": "Плануємо його каструвати",
  "pack.flow.z_kastr.o.no.sub.plan_neuter.warn": "<b>За останніми даними, краще обрати вазектомію.</b> Вона механічно запобігає заплідненню, а гормони залишаються; самиці можна зберегти яєчники. Класичну кастрацію роби лише після дорослішання: це залежить від розвитку й породи, пса чи суку не раніше, ніж після статевого дозрівання, великі породи якомога пізніше. У французьких бульдогів кастрація до 12 місяців підвищувала ризик проблем із міжхребцевими дисками приблизно у 2× у самців і приблизно в 10× у самиць.",
  "pack.flow.z_kastr.o.no.sub.plan_neuter.warnT": "Чому вазектомія",
  "pack.flow.z_kastr.o.no.sub.puppies": "Плануємо цуценят, бо це мило",
  "pack.flow.z_kastr.o.no.sub.puppies.warn": "Розведення собак без документів є правопорушенням. У світі надто багато непотрібних собак у притулках без шансу вибратися, зокрема через нелегальне розведення й «нових» цуценят. Хто розводить собак у такий спосіб, чинить гріх проти собачого роду. Псу не потрібне потомство; за цим стоїть лише людська сентиментальність і надія на прибуток. Правда в тому, що такий шлях приносить тільки страждання.",
