  "pack.flow.z_ocko.t": "Коли його востаннє щеплювали?",
  "pack.flow.z_ocko.note": "Титри, пропущені вакцини, реакція після щеплення.",
  "pack.flow.z_ocko.tip0": "<b>Комплексна вакцина</b> означає одну ін'єкцію проти кількох хвороб: чуми м'ясоїдних, парвовірусу, гепатиту, часто й лептоспірозу. У ветеринарному паспорті вона позначена як DHPPi/L.",
  "pack.flow.z_ocko.tip1": "<b>Щеплення від сказу обов'язкове за людськими законами</b>, і тест на антитіла юридично його не замінює. Але в собачому світі надмірна вакцинація може зашкодити: антитіла виявляються в пса навіть через багато років, іноді на все життя, тож повторні щеплення часто зайві або навіть шкідливі. Якщо не хочеш вводити псу непотрібні вакцини, існує аналіз крові на антитіла. Якщо вони є, зваж, чи варто щеплювати.",
  "pack.flow.z_ocko.tipT": "Що треба знати про щеплення",
  "pack.flow.z_ocko.f0": "Сказ",
  "pack.flow.z_ocko.f1": "Комплексна вакцина",
  "pack.flow.z_parazity.t": "Як ти вирішуєш питання кишкових паразитів?",
  "pack.flow.z_parazity.tip0": "<b>Порада: спершу аналіз калу.</b> Копрологія покаже, чи є що лікувати. Подумай, чи правильно годувати пса хімією просто про всяк випадок. Регулярні таблетки не такі невинні, як здається. Це бізнес, за який платить собаче здоров'я. Використовуй їх лише тоді, коли це необхідно й має сенс, тобто коли паразит справді є.",
  "pack.flow.z_parazity.tipT": "Що треба знати про паразитів",
